function renderCartPage(){renderSavedMenu();const entries=Object.entries(S.customerCart).filter(x=>x[1]>0&&S.products.some(p=>p.id===x[0]));$('#cartPageItems').innerHTML=entries.length?entries.map(([id,q])=>{const p=S.products.find(x=>x.id===id);const unit=Store.customerUnitPrice(p,q),wholesale=p.wholesaleQty&&q>=p.wholesaleQty&&p.wholesalePrice<=unit;const promo=S.promoUnitPrice[p.id]&&S.promoUnitPrice[p.id]<p.price;return `<div class="sheet-row"><img src="${p.img}" alt="${p.name}"><div><b>${p.name}</b><br><small>${money(unit)} × ${String(q).replace('.',',')} ${p.unit||'pcs'}</small>${wholesale?'<span class="wholesale-note">Harga '+p.wholesaleLabel+' aktif</span>':promo?'<span class="wholesale-note">Harga promo kilat aktif</span>':''}</div><div class="qty"><button class="mini-btn" data-c-dec="${id}" aria-label="Kurangi ${p.name}">−</button><b>${String(q).replace('.',',')}</b><button class="mini-btn plus" data-c-inc="${id}" aria-label="Tambah ${p.name}">+</button></div></div>`}).join(''):'<div class="empty-note">Keranjangmu masih kosong.<br><small>Tambahkan barang dari Beranda atau Produk.</small></div>';const totals=cartTotals();$('#cartGross').textContent=money(totals.gross);$('#cartSubtotal').textContent=$('#cartPageTotal').textContent=money(totals.total);$('#cartDiscount').textContent='−'+money(totals.discount);$('#cartDiscountRow').hidden=totals.discount===0;$$('[data-c-dec]').forEach(b=>b.onclick=()=>{const id=b.dataset.cDec,p=S.products.find(x=>x.id===id);if(p&&typeof isWeightUnit==='function'&&isWeightUnit(p.unit)){const nq=Math.round((S.customerCart[id]-0.1)*10)/10;if(nq<0.1)delete S.customerCart[id];else S.customerCart[id]=nq;}else{S.customerCart[id]--;if(S.customerCart[id]<=0)delete S.customerCart[id];}updateCustomerCart()});$$('[data-c-inc]').forEach(b=>b.onclick=()=>{const id=b.dataset.cInc,p=S.products.find(x=>x.id===id);if(p&&typeof isWeightUnit==='function'&&isWeightUnit(p.unit)){S.customerCart[id]=Math.round((S.customerCart[id]+0.1)*10)/10;}else{S.customerCart[id]++;}updateCustomerCart()});updateCheckoutSummary()}
function renderSavedMenu(){const area=$('#savedMenuArea');if(!S.savedMenu){area.innerHTML='';return}const count=Object.values(S.savedMenu).reduce((a,b)=>a+b,0);area.innerHTML=`<section class="saved-menu"><div><b>Menu belanja rumah</b><small>${count} barang · tersimpan selama sesi ini</small></div><button id="useSavedMenu">Gunakan</button></section>`;$('#useSavedMenu').onclick=()=>{S.customerCart=Object.assign({},S.savedMenu);updateCustomerCart();toast('Menu tersimpan dimasukkan')}}
