function renderAdminProducts(){renderCategoryChips();const query=($('#adminProductSearch')?$('#adminProductSearch').value:'').trim().toLocaleLowerCase('id-ID'),matches=S.products.filter(p=>p.name.toLocaleLowerCase('id-ID').includes(query)),preferred=matches.filter(p=>p.cat===S.adminCat),list=[...preferred,...matches.filter(p=>!preferred.includes(p))],empty=$('#adminProductEmpty');$('#adminProductCount').textContent=list.length;$('#adminProducts').innerHTML=list.map(p=>{const qty=S.adminCart[p.id]||0,action=qty===0?`<button class="add" data-add-a="${p.id}" aria-label="Tambah ${escapeHtml(p.name)}">+</button>`:`<div class="kasir-stepper" aria-label="Jumlah ${escapeHtml(p.name)}"><button data-row-dec="${p.id}" aria-label="Kurangi ${escapeHtml(p.name)}">\u2212</button><b>${qty}</b><button data-row-inc="${p.id}" aria-label="Tambah ${escapeHtml(p.name)}">+</button></div>`;return `<article class="admin-product"><img src="${p.img}" alt="${escapeHtml(p.name)}"><div class="kasir-row-info"><h3>${escapeHtml(p.name)}</h3><div class="kasir-row-sub">${money(p.price)} \u00B7 stok ${stockText(p)}</div></div><div class="kasir-row-action">${action}</div></article>`}).join('');if(empty)empty.hidden=list.length>0;const bump=id=>{S.adminCart[id]=(S.adminCart[id]||0)+1;renderAdminCart();renderAdminProducts()};$$('[data-add-a]').forEach(b=>b.onclick=()=>{bump(b.dataset.addA);toast(pName(b.dataset.addA)+' masuk keranjang')});$$('[data-row-inc]').forEach(b=>b.onclick=()=>bump(b.dataset.rowInc));$$('[data-row-dec]').forEach(b=>b.onclick=()=>{const id=b.dataset.rowDec;S.adminCart[id]--;if(S.adminCart[id]<=0)delete S.adminCart[id];renderAdminCart();renderAdminProducts()})}
