function coinRedemption(totals){if(!S.coinProgramEnabled||!S.coinRedeemEnabled||S.coinValue<=0)return {coins:0,value:0};const maxValue=Math.floor(totals.total*S.coinRedeemPercent/100),coins=Math.max(0,Math.min(S.coinBalance,Math.floor(maxValue/S.coinValue)));return {coins:coins,value:coins*S.coinValue}}function updateCheckoutSummary(){const totals=cartTotals(),fee=S.fulfillment==='delivery'?5000:0,redeem=coinRedemption(totals);if($('#checkoutItemsTotal')){$('#checkoutItemsTotal').textContent=money(totals.total);$('#checkoutDeliveryFee').textContent=money(fee);$('#checkoutGrandTotal').textContent=money(Math.max(0,totals.total+fee-redeem.value));$('#checkoutCoinDiscount').textContent='−'+money(redeem.value);$('#checkoutCoinRow').hidden=redeem.value===0;$('#coinRedeemBalance').textContent='Saldo '+S.coinBalance.toLocaleString('id-ID')+' koin · '+money(S.coinBalance*S.coinValue);$('#coinRedeemValue').textContent=redeem.value?'−'+redeem.coins.toLocaleString('id-ID')+' koin · '+money(redeem.value):'Potongan Rp0';$('#coinRedeemLimit').textContent='Maks. '+S.coinRedeemPercent+'% belanja · 1 koin = '+money(S.coinValue);$('#coinRedeemBox').classList.toggle('coin-disabled',!S.coinProgramEnabled||S.coinBalance===0||S.coinRedeemPercent===0);$('#coinRedeemToggle').classList.toggle('active',S.coinRedeemEnabled);$('#coinRedeemToggle').setAttribute('aria-pressed',String(S.coinRedeemEnabled));$('#coinRedeemToggle').textContent=S.coinRedeemEnabled?'Digunakan':'Gunakan';$('#confirmOrderBtn').textContent=S.fulfillment==='delivery'?'Pesan & minta diantar':'Pesan & ambil di warung'}}
