// Mode Anggaran V2: pelanggan pilih produk, sistem hitungkan qty
let budgetSelectedIds=new Set();
function renderBudgetProductList(){
  const box=$('#budgetProductList');if(!box)return;
  const list=getBudgetEligible().sort((a,b)=>a.name.localeCompare(b.name,'id'));
  box.innerHTML=list.length?list.map(p=>`<label class="stock-task"><input type="checkbox" class="stock-check" data-budget-pick="${p.id}" ${budgetSelectedIds.has(p.id)?'checked':''}><span class="task-copy"><b>${escapeHtml(p.name)}</b><small>${money(p.price)} · Stok ${p.stock}</small></span></label>`).join(''):'<div class="empty-note">Belum ada produk untuk Mode Anggaran.<br><small>Admin dapat mengaktifkannya di form produk.</small></div>';
  box.querySelectorAll('[data-budget-pick]').forEach(cb=>cb.onchange=()=>{if(cb.checked)budgetSelectedIds.add(cb.dataset.budgetPick);else budgetSelectedIds.delete(cb.dataset.budgetPick);calculateBudget()});
  $('#budgetSelectedCount').textContent=`(${budgetSelectedIds.size} dipilih)`;
}
function calculateBudget(){
  const amount=Number(($('#budgetAmountInput').value||'').replace(/\D/g,''))||0;
  const selected=getBudgetEligible().filter(p=>budgetSelectedIds.has(p.id)).sort((a,b)=>a.price-b.price);
  if(!amount||!selected.length){previewBudgetV2({});return}
  let left=amount;const out={};
  for(const p of selected){
    if(left<p.price)break;
    const maxQ=Math.min(p.budgetMaxQty||4,p.stock,Math.floor(left/p.price));
    if(maxQ>0){out[p.id]=maxQ;left-=maxQ*p.price}
  }
  previewBudgetV2(out);
}
$('#budgetAmountInput').oninput=()=>calculateBudget();
