async function startBarcodeScanner(){
  await stopBarcodeScanner();
  const mySession=++barcodeScanSession;
  setScannerHint('Menyiapkan kamera…');
  if(!barcodeLibReady()){setScannerHint('Browser tidak mendukung pindai otomatis · pakai ketik manual di bawah');return;}
  try{
    if(navigator.permissions&&navigator.permissions.query){
      const ps=await navigator.permissions.query({name:'camera'});
      if(ps.state==='denied'){
        setScannerHint('Izin kamera ditolak · aktifkan di Pengaturan HP > Aplikasi > Izin');
        toast('Izin kamera ditolak · cek Pengaturan HP');
        return;
      }
    }
  }catch(e){}
  if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){
    setScannerHint('Browser tidak mendukung kamera · pakai ketik manual di bawah');
    return;
  }
  try{
    setScannerHint('Meminta izin kamera…');
    const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});
    if(mySession!==barcodeScanSession){try{stream.getTracks().forEach(t=>t.stop());}catch(e){}return;}
    barcodeStream=stream;
    const viewport=$('#scannerViewport');
    if(viewport){
      viewport.innerHTML='';
      const video=document.createElement('video');
      video.setAttribute('autoplay','');video.setAttribute('playsinline','');video.setAttribute('muted','');
      video.style.width='100%';video.style.height='100%';video.style.objectFit='cover';
      video.srcObject=stream;
      viewport.appendChild(video);
      try{await video.play();}catch(e){}
    }
    if(mySession!==barcodeScanSession)return;
    setScannerHint('Arahkan barcode ke dalam bingkai');
    let detector=null;
    try{
      detector=new BarcodeDetector({formats:['ean_13','ean_8','code_128','code_39','upc_a','upc_e','itf','codabar','qr_code']});
    }catch(e){
      try{detector=new BarcodeDetector();}catch(e2){detector=null;}
    }
    if(!detector){setScannerHint('Pemindai tidak tersedia · pakai ketik manual di bawah');return;}
    barcodeDetectTimer=setInterval(async()=>{
      if(mySession!==barcodeScanSession)return;
      if(barcodeScanBusy)return;
      try{
        const videoEl=viewport?viewport.querySelector('video'):null;
        if(!videoEl||videoEl.readyState<2)return;
        const codes=await detector.detect(videoEl);
        if(codes&&codes.length){
          const code=String((codes[0]&&codes[0].rawValue)||'').trim();
          if(code)onBarcodeScanned(code);
        }
      }catch(e){}
    },500);
  }catch(err){
    if(mySession!==barcodeScanSession)return;
    const nm=err&&(err.name||'');
    if(nm==='NotAllowedError'){
      setScannerHint('Izin kamera ditolak · aktifkan di Pengaturan HP > Aplikasi > Izin');
    }else if(nm==='NotFoundError'){
      setScannerHint('Kamera tidak ditemukan di HP ini');
    }else if(nm==='NotReadableError'){
      setScannerHint('Kamera dipakai aplikasi lain · tutup dulu');
    }else{
      setScannerHint('Gagal memulai kamera · atau ketik manual di bawah');
    }
    toast('Gagal memulai kamera');
  }
}

function onBarcodeScanned(decodedText){
  const code=String(decodedText||'').trim();
  if(!code||barcodeScanBusy)return;
  barcodeScanBusy=true;
  handleBarcodeCode(code);
}
let barcodeScanTarget=null;
function handleBarcodeCode(rawCode){
  const code=String(rawCode||'').trim();
  stopBarcodeScanner();
  if(!code){closeSheets();return;}
  if(barcodeScanTarget){
    const input=$('#'+barcodeScanTarget);barcodeScanTarget=null;
    closeSheets();openSheet('productFormModal');
    if(input){input.value=code;input.focus();}
    toast('Barcode terisi: '+code);
    return;
  }
  /* Opsi A: kode member KQ-XXXXXXXX → identifikasi member kasir */
  if(/^KQ-/i.test(code)){closeSheets();identifyKasirMember(code.toUpperCase());return;}
  const product=(S.products||[]).find(p=>String(p.barcode||'').trim()===code);
  closeSheets();
  if(!product){toast('Barcode tidak dikenali · produk belum terdaftar');return;}
  S.adminCart[product.id]=(S.adminCart[product.id]||0)+1;
  renderAdminCart();
  playNotification('order','mimi',false);
  toast(product.name+' masuk keranjang');
}
/* Opsi A: lookup member by memberCode untuk identifikasi di kasir */
async function identifyKasirMember(code){
  /* [FIX SOP 2026-10-16] Validasi format: KQ- + 8 alfanumerik.
   * Tanpa ini, "KQ-", "KQ-!!!", "KQ-WM-2026" memicu query sia-sia. */
  if(!/^KQ-[A-Z0-9]{8}$/i.test(String(code||''))){toast('Kode member tidak valid');return;}
  try{
    if(!window.FB||!FB.db)throw new Error('offline');
    const snap=await FB.db.collection('customers').where('memberCode','==',code).limit(2).get();
    if(snap.empty){toast('Member tidak ditemukan');return;}
    /* [FIX SOP 2026-10-16 #2] Deteksi kolisi memberCode: 8 char awal UID
     * secara teori bisa sama antar user. Tolak daripada salah identifikasi
     * (soal uang & identitas) — admin selesaikan manual di Data Pelanggan. */
    if(snap.size>1){toast('Data member ganda — hubungi admin');return;}
    const doc=snap.docs[0],data=doc.data()||{};
    if(data.approvalStatus!=='approved'){toast('Member belum disetujui');return;}
    S.kasirMember={uid:doc.id,name:data.name||'Member',memberCode:code,coins:Math.max(0,Math.round(Number(data.coins)||0))};
    S.kasirRedeem=false;
    renderKasirMember();
    toast('Member: '+S.kasirMember.name);
  }catch(e){toast('Gagal cari member');}
}
function clearKasirMember(){S.kasirMember=null;S.kasirRedeem=false;renderKasirMember();}
function renderKasirMember(){
  const badge=$('#kasirMemberBadge');if(!badge)return;
  const m=S.kasirMember;
  badge.hidden=!m;
  if(m){
    const total=adminCartPaymentTotal(),earned=kasirEarnedCoins(total);
    badge.innerHTML=`<span>👤 ${escapeHtml(m.name)}</span><span class="kasir-coin-info">Saldo: ${m.coins.toLocaleString('id-ID')} koin · Akan dapat: ${earned.toLocaleString('id-ID')}</span><button data-clear-member aria-label="Hapus member">×</button>`;
    const btn=badge.querySelector('[data-clear-member]');
    if(btn)btn.onclick=clearKasirMember;
  }
}
/* Backfill: generate memberCode untuk member lama yang belum punya (idempotent) */
async function backfillMemberCodes(){
  try{
    if(!window.FB||!FB.db)return 0;
    const snap=await FB.db.collection('customers').where('approvalStatus','==','approved').get();
    const batch=FB.db.batch();let n=0;
    snap.forEach(doc=>{const d=doc.data()||{};
      if(!d.memberCode){batch.update(doc.ref,{memberCode:'KQ-'+String(doc.id).slice(0,8).toUpperCase()});n++;}
    });
    if(n>0)await batch.commit();
    return n;
  }catch(e){return 0;}
}
