$('#downloadReceipt').onclick=()=>{if(!S.lastReceipt)return toast('Belum ada transaksi untuk diunduh');const receipt=S.lastReceipt,lines=['WARUNGE MIMI','Warung kelontong warga',receipt.at,'----------------------------',...receipt.items.map(x=>x.name+' x'+x.qty+'  '+money(x.total)),'----------------------------','TOTAL  '+money(receipt.total),'UANG DITERIMA  '+money(receipt.cashReceived||receipt.total),'KEMBALIAN  '+money(receipt.change||0),'Terima kasih'];const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='struk-warunge-mimi.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Struk 58mm diunduh')};renderReceipt();
const logoutCustomerBtn=$('#logoutCustomerBtn')||$('#logoutCustomer');if(logoutCustomerBtn)logoutCustomerBtn.onclick=()=>{S.sessionRole=null;S.sessionName=null;S.sessionStartedAt=null;S.activeCustomerId=null;S.activeOrder=null;S.isGuest=true;S.pendingGuestAction=null;Store.logout();closeSheets();go('gateway');toast('Sesi pelanggan ditutup')};


